    "动态规划\\换根DP\\Untitled1.cpp": "#include<bits/stdc++.h>\r\nusing namespace std;\r\n#define int long long\r\nvector<int> G1[1000010];\r\nint n,ans=0,jd=1;\r\nint sz[1000010],f[1000010],dp[1000010];\r\nvoid dfs1(int st,int pa){\r\n\tsz[st]=1,dp[st]=0;\r\n\tfor(auto i:G1[st]){\r\n\t\tif(i==pa) continue;\r\n\t\tdfs1(i,st);\r\n\t\tsz[st]+=sz[i];\r\n\t\tdp[st]+=dp[i]+sz[i];\r\n\t}\r\n}\r\nvoid dfs2(int st,int pa){\r\n\tsz[st]=1,dp[st]=0;\r\n\tfor(auto i:G1[st]){\r\n\t\tif(i==pa) continue;\r\n\t\tf[i]=f[st]+n-2*sz[i];\r\n\t\tdfs2(i,st);\r\n\t}\r\n}\r\nsigned main(){\r\n    cin>>n;\r\n    for(int i=1;i<n;i++){\r\n\t\tint u,v;cin>>u>>v;\r\n\t\tG1[u].push_back(v);\r\n\t\tG1[v].push_back(u);\r\n\t}\r\n\tdfs1(1,-1);\r\n\tdfs2(1,-1);\r\n\tfor(int i=1;i<=n;i++){\r\n\t\tif(ans<f[i]){ans=max(ans,f[i]);jd=i;}\r\n\t}\r\n\tcout<<jd;\r\n    return 0;\r\n}\r\n",
