    "动态规划\\子集DP\\Untitled1--xesir.cpp": "#include<bits/stdc++.h>\n#define endl '\\n'\n#define fi first\n#define se second\n#define lowbit(x) (x&(-x))\n#define int long long\nusing namespace std;\ntypedef pair<int,int> PII;\ntypedef long long ll;\nconst int INF=INT_MAX;\n//int cnt=0;\ninline int read();\ninline void write(int x);\nsigned main(){\n//    freopen(\".in\",\"r\",stdin);\n//    freopen(\".out\",\"w\",stdout);\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);cout.tie(nullptr);\n    int W,n;cin>>W>>n;\n    vector<int> t(1<<n,0),w(1<<n,0),dp(1<<n,INF);\n    for(int i=0;i<n;i++){\n        int a,b;cin>>a>>b;\n        for(int j=0;j<(1<<n);j++){\n            if(j&(1<<i)){\n                t[j]=max(t[j],a);\n                w[j]+=b;\n            }\n        }\n    }\n    for(int i;i<(1<<n);i++){\n        if(w[i]<=W) dp[i]=t[i];\n        for(int j=i;j;j=i&(j-1)){\n            if(w[i^j]<=W) dp[i]=min(dp[i],dp[j]+t[i^j]);\n        }\n    }\n    cout<<dp[(1<<n)-1]<<'\\n';\n    return 0;\n}\ninline int read(){\n    int x=0,f=1;\n    char ch=getchar();\n    while(ch< '0'||ch>'9'){\n        if(ch=='-') f=-1;\n        ch=getchar();\n    }\n    while(ch>='0'&&ch<='9'){\n        x=(x<<1)+(x<<3)+(ch^48);\n        ch=getchar();\n    }\n    return x*f;\n}\ninline void write(int x){\n    if(x<0){\n        putchar('-');\n        x=-x;\n    }\n    if(x>9) write(x/10);\n    putchar(x%10+'0');\n}\n#include<bits/stdc++.h>\n#define endl '\\n'\n#define fi first\n#define se second\n#define lowbit(x) (x&(-x))\n#define int long long\nusing namespace std;\ntypedef pair<int,int> PII;\ntypedef long long ll;\nconst int N=1<<19,INF=INT_MAX;\n//int cnt=0;\nint a[N];\nPII f[N];\ninline int read();\ninline void write(int x);\nPII mxp(PII a,PII b){\n    if(a.fi<b.fi) swap(a,b);\n    if(a.se<b.fi) a.se=b.fi;\n    return a;\n}\nsigned main(){\n//    freopen(\".in\",\"r\",stdin);\n//    freopen(\".out\",\"w\",stdout);\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);cout.tie(nullptr);\n    int n;cin>>n;\n    for(int i=0;i<(1<<n);i++){\n        cin>>a[i];\n        f[i]={a[i],-INF};\n    }\n    for(int i=0;i<n;i++){\n        for(int sta=(1<<n)-1;sta>=0;sta--){\n            if(sta&(1<<i)) f[sta]=mxp(f[sta],f[sta^(1<<i)]);\n        }\n    }\n    int ans=0;\n    for(int i=1;i<(1<<n);i++){\n        ans=max(f[i].fi+f[i].se,ans);\n        cout<<ans<<'\\n';\n    }\n    return 0;\n}\ninline int read(){\n    int x=0,f=1;\n    char ch=getchar();\n    while(ch< '0'||ch>'9'){\n        if(ch=='-') f=-1;\n        ch=getchar();\n    }\n    while(ch>='0'&&ch<='9'){\n        x=(x<<1)+(x<<3)+(ch^48);\n        ch=getchar();\n    }\n    return x*f;\n}\ninline void write(int x){\n    if(x<0){\n        putchar('-');\n        x=-x;\n    }\n    if(x>9) write(x/10);\n    putchar(x%10+'0');\n}\n",
    "动态规划\\树形DP\\树状01背包\\Untitled1.cpp": "#include<bits/stdc++.h>\r\nusing namespace std;\r\n/*U436983*/\r\nint N , V , root;\r\nvector<pair<int,int>> A;\r\nvector<vector<int>> son;\r\nvector<vector<int>> dp;\r\nvoid dfs(int idx)\r\n{\r\n\tfor(int i = A[idx].first;i <= V;i++) dp[idx][i] = A[idx].second;\r\n\tfor(int i : son[idx])\r\n\t{\r\n\t\tdfs(i);\r\n\t\tfor(int j = V ; j > A[idx].first ; j--)\r\n\t\t{\r\n\t\t\tfor(int k = 1;j - k >= A[idx].first;k++)\r\n\t\t\t{\r\n\t\t\t\tdp[idx][j] = max(dp[idx][j - k] + dp[i][k] , dp[idx][j]);\r\n\t\t\t}\r\n\t\t}\r\n\t}\r\n}\r\nint main()\r\n{\r\n\tios::sync_with_stdio(false);\r\n\tcin.tie(nullptr);cout.tie(nullptr);\r\n\t\r\n\tcin >> N >> V;\r\n\tdp.resize(N + 1,vector<int>(V + 1,0));\r\n\tA.resize(N + 1);\r\n\tson.resize(N + 1,vector<int>());\r\n\tfor(int i = 1;i <= N;i++)\r\n\t{\r\n\t\tint p;\r\n\t\tcin >> A[i].first >> A[i].second >> p;\r\n\t\tif(p == -1) root = i;\r\n\t\telse son[p].emplace_back(i);\r\n\t}\r\n\tdfs(root);\r\n\tcout << dp[root][V];\r\n\treturn 0;\t\r\n} \r\n",
    "动态规划\\树形背包优化\\Untitled1.cpp": "#include<bits/stdc++.h>\r\n#define endl '\\n'\r\n#define fi first\r\n#define se second\r\n#define lowbit(x) (x&(-x))\r\n#define int long long\r\nusing namespace std;\r\ntypedef pair<int,int> PII;\r\ntypedef long long ll;\r\nconst int N=2e3+10;\r\nint cnt=0,n,k;\r\nvector<PII> G1[N];\r\nint siz[N],dp[N][N];\r\nvoid dfs1(int x,int fa){\r\n\tsiz[x]=1;\r\n\tfor(auto i:G1[x]){\r\n\t\tif(i.fi==fa) continue;\r\n\t\tdfs1(i.fi,x);\r\n\t\tsiz[x]+=siz[i.fi];\r\n\t}\r\n}\r\nvoid dfs2(int x,int fa){\r\n\tdp[x][0]=dp[x][1]=0;\r\n\tfor(auto j:G1[x]){\r\n\t\tif(j.fi==fa) continue;\r\n        dfs2(j.fi,x);\r\n\t\tfor(int m=min(k,siz[x]);m>=0;m--){\r\n\t\t\tif(dp[x][m]!=-1) dp[x][m]+=dp[j.fi][0]+siz[j.fi]*(n-k-siz[j.fi])*j.se;\r\n\t\t\tfor(int v=min(m,siz[j.fi]);v>0;v--){\r\n\t\t\t\tif(dp[x][m-v]==-1) continue;\r\n\t\t\t\tint tot=v*(k-v)+(siz[j.fi]-v)*(n-k-siz[j.fi]+v);\r\n\t\t\t\tdp[x][m]=max(dp[x][m],dp[x][m-v]+dp[j.fi][v]+tot*j.se);\r\n\t\t\t}\r\n\t\t}\t\t\r\n\t}\r\n}\r\ninline int read();\r\ninline void write(int x);\r\nsigned main(){\r\n//    freopen(\".in\",\"r\",stdin);\r\n//    freopen(\".out\",\"w\",stdout);\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);cout.tie(nullptr);\r\n    memset(dp,-1,sizeof dp);\r\n\tcin>>n>>k;\r\n    if(n-k<k) k=n-k;\r\n\tfor(int i=1;i<n;i++){\r\n\t\tint u,v,w;cin>>u>>v>>w;\r\n\t\tG1[u].push_back({v,w});\r\n\t\tG1[v].push_back({u,w});\r\n\t}\r\n\tdfs1(1,0);\r\n\tdfs2(1,0);\r\n\tcout<<dp[1][k];\r\n    return 0;\r\n}\r\ninline int read(){\r\n    int x=0,f=1;\r\n    char ch=getchar();\r\n    while(ch< '0'||ch>'9'){\r\n        if(ch=='-') f=-1;\r\n        ch=getchar();\r\n    }\r\n    while(ch>='0'&&ch<='9'){\r\n        x=(x<<1)+(x<<3)+(ch^48);\r\n        ch=getchar();\r\n    }\r\n    return x*f;\r\n}\r\ninline void write(int x){\r\n    if(x<0){\r\n        putchar('-');\r\n        x=-x;\r\n    }\r\n    if(x>9) write(x/10);\r\n    putchar(x%10+'0');\r\n}\r\n",
