    "题目专辑\\数学\\可乐\\代码--xesir.cpp": "#include <bits/stdc++.h>\nusing namespace std;\nconst int mod=2017,N=50;\n#define pb push_back\n#define vi vector<int>\n#define v2 vector<vector<int>>\nv2 mtxi(int n){\n    v2 c(n,vi(n,0));\n    for(int i=0;i<n;i++) c[i][i]=1;\n    return c;\n}\nv2 muljz(v2 a,v2 b){\n    int m=a.size(),p=a[0].size(),n=b[0].size();\n    v2 c(m,vi(n,0));\n    for(int i=0;i<m;i++){\n        for(int k=0;k<p;k++){\n            if(a[i][k]==0) continue;\n            for(int j=0;j<n;j++) c[i][j]=(c[i][j]%mod+a[i][k]*b[k][j]%mod)%mod;\n        }\n    }\n    return c;\n}\nv2 ksmjz(v2 a,int k){\n    int n=a.size();\n    v2 res=mtxi(n);\n    while(k){\n        if(k&1) res=muljz(res,a);\n        a=muljz(a,a);\n        k>>=1;\n    }\n    return res;\n}\nsigned main(){\n    ios::sync_with_stdio(0);\n    cin.tie(0);cout.tie(0);\n    int n,m,t,ans=0;cin>>n>>m;\n    v2 x(n+1,vi(n+1,0)),y(n+1,vi(n+1,0));\n    x[1][1]=1;\n    for(int i=0;i<=n;i++) y[i][i]=1,y[i][0]=1;\n    while(m--){\n        int u,v;cin>>u>>v;\n        //u--;v--;\n        y[u][v]=y[v][u]=1;\n    }\n    cin>>t;\n    v2 res=muljz(x,ksmjz(y,t));\n    for(int i=0;i<=n;i++) ans=(ans%mod+res[1][i]%mod);\n    cout<<ans%mod;\n    return 0;\n}\n",
    "题目专辑\\动态规划\\宝藏\\代码--xesir.cpp": "#include<bits/stdc++.h>\r\n#define endl '\\n'\r\n#define fi first\r\n#define se second\r\n#define lowbit(x) (x&(-x))\r\n#define int long long\r\nusing namespace std;\r\ntypedef pair<int,int> PII;\r\ntypedef long long ll;\r\nconst int N=15,M=(1<<12);\r\nint n,m,cnt;\r\nint cot[M][M],dp[N][M],G1[N][N];\r\ninline int read();\r\ninline void write(int x);\r\nsigned main(){\r\n//    freopen(\".in\",\"r\",stdin);\r\n//    freopen(\".out\",\"w\",stdout);\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);cout.tie(nullptr);\r\n\tcin>>n>>m;\r\n    \r\n\tmemset(G1,0x3f,sizeof G1);\r\n\tmemset(dp,0x3f,sizeof dp);\r\n\tint inf=dp[0][0];\r\n\tcnt=inf;\r\n    if(n==1){\r\n        cout<<0;return 0;\r\n    }\r\n\tfor(int i=1;i<=m;i++){\r\n\t\tint u,v,w;cin>>u>>v>>w;\r\n\t\tG1[u][v]=min(G1[u][v],w);\r\n\t\tG1[v][u]=min(G1[v][u],w);\r\n\t}\r\n\tfor(int i=1;i<(1<<n);i++){\r\n\t\tfor(int j=i;j;j=(j-1)&i){\r\n            if(j==i) continue;\r\n\t\t\tfor(int t=1;t<=n;t++){\r\n\t\t\t\tint tmp=inf;\r\n\t\t\t\tif(!(((i^j)>>(t-1))&1)) continue;\r\n\t\t\t\tfor(int l=1;l<=n;l++){\r\n\t\t\t\t\tif((j>>(l-1))&1) tmp=min(tmp,G1[l][t]);\r\n\t\t\t\t}\r\n                if(tmp>=inf){\r\n\t\t\t\t\tcot[j][i]=inf;break;\r\n\t\t\t\t}else cot[j][i]+=tmp;\r\n\t\t\t}\r\n\t\t}\r\n\t}\r\n\tfor(int u=1;u<=n;u++){\r\n\t\tmemset(dp,0x3f,sizeof dp);\r\n\t\tdp[0][1<<(u-1)]=0;\r\n\t\tfor(int i=1;i<n;i++){\r\n\t\t\tfor(int j=1;j<(1<<n);j++){\r\n\t\t\t\tfor(int k=j;k;k=(k-1)&j){\r\n                    if(j==k) continue;\r\n\t\t\t\t\tif(cot[k][j]!=inf) dp[i][j]=min(dp[i][j],dp[i-1][k]+i*cot[k][j]);\r\n\t\t\t\t}\r\n\t\t\t}\r\n\t\t\tcnt=min(cnt,dp[i][(1<<n)-1]);\r\n\t\t}\r\n\t}\r\n\tcout<<cnt;\r\n    return 0;\r\n}\r\ninline int read(){\r\n    int x=0,f=1;\r\n    char ch=getchar();\r\n    while(ch< '0'||ch>'9'){\r\n        if(ch=='-') f=-1;\r\n        ch=getchar();\r\n    }\r\n    while(ch>='0'&&ch<='9'){\r\n        x=(x<<1)+(x<<3)+(ch^48);\r\n        ch=getchar();\r\n    }\r\n    return x*f;\r\n}\r\ninline void write(int x){\r\n    if(x<0){\r\n        putchar('-');\r\n        x=-x;\r\n    }\r\n    if(x>9) write(x/10);\r\n    putchar(x%10+'0');\r\n}\r\n",
    "题目专辑\\动态规划\\宝藏\\代码.cpp": "#include<bits/stdc++.h>\r\n#define endl '\\n'\r\n#define fi first\r\n#define se second\r\n#define lowbit(x) (x&(-x))\r\n#define int long long\r\nusing namespace std;\r\ntypedef pair<int,int> PII;\r\ntypedef long long ll;\r\nconst int N=15,M=(1<<12);\r\nint n,m,cnt;\r\nint cot[M][M],dp[N][M],G1[N][N];\r\ninline int read();\r\ninline void write(int x);\r\nsigned main(){\r\n//    freopen(\".in\",\"r\",stdin);\r\n//    freopen(\".out\",\"w\",stdout);\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);cout.tie(nullptr);\r\n    cin>>n>>m;\r\n\r\n    memset(G1,0x3f,sizeof G1);\r\n    memset(dp,0x3f,sizeof dp);\r\n    int inf=dp[0][0];\r\n    cnt=inf;\r\n    if(n==1){\r\n        cout<<0;return 0;\r\n    }\r\n    for(int i=1;i<=m;i++){\r\n        int u,v,w;cin>>u>>v>>w;\r\n        G1[u][v]=min(G1[u][v],w);\r\n        G1[v][u]=min(G1[v][u],w);\r\n    }\r\n    for(int i=1;i<(1<<n);i++){\r\n        for(int j=i;j;j=(j-1)&i){\r\n            if(j==i) continue;\r\n            for(int t=1;t<=n;t++){\r\n                int tmp=inf;\r\n                if(!(((i^j)>>(t-1))&1)) continue;\r\n                for(int l=1;l<=n;l++){\r\n                    if((j>>(l-1))&1) tmp=min(tmp,G1[l][t]);\r\n                }\r\n                if(tmp>=inf){\r\n                    cot[j][i]=inf;break;\r\n                }else cot[j][i]+=tmp;\r\n            }\r\n        }\r\n    }\r\n    for(int u=1;u<=n;u++){\r\n        memset(dp,0x3f,sizeof dp);\r\n        dp[0][1<<(u-1)]=0;\r\n        for(int i=1;i<n;i++){\r\n            for(int j=1;j<(1<<n);j++){\r\n                for(int k=j;k;k=(k-1)&j){\r\n                    if(j==k) continue;\r\n                    if(cot[k][j]!=inf) dp[i][j]=min(dp[i][j],dp[i-1][k]+i*cot[k][j]);\r\n                }\r\n            }\r\n            cnt=min(cnt,dp[i][(1<<n)-1]);\r\n        }\r\n    }\r\n    cout<<cnt;\r\n    return 0;\r\n}\r\ninline int read(){\r\n    int x=0,f=1;\r\n    char ch=getchar();\r\n    while(ch< '0'||ch>'9'){\r\n        if(ch=='-') f=-1;\r\n        ch=getchar();\r\n    }\r\n    while(ch>='0'&&ch<='9'){\r\n        x=(x<<1)+(x<<3)+(ch^48);\r\n        ch=getchar();\r\n    }\r\n    return x*f;\r\n}\r\ninline void write(int x){\r\n    if(x<0){\r\n        putchar('-');\r\n        x=-x;\r\n    }\r\n    if(x>9) write(x/10);\r\n    putchar(x%10+'0');\r\n}\r\n",
