    "题目专辑\\图论\\基础最短路练习题\\代码--xesir.cpp": "#include <bits/stdc++.h>\nusing namespace std;\n//#define int long long\n#define PII pair<int,int>\n#define fi first\n#define se second\n//#define pb push_back\nconst int N=1e5+10;\nint n,m,q;\nvector<PII> G1[N];\nint h[N],vis[N];\nvoid dfs(int x){\n\tvis[x]=1;\n\t//cout<<x<<\" \"<<h[x]<<endl;\n\tfor(auto i:G1[x]){\n\t\tif(!vis[i.fi]){\n\t\t\th[i.fi]=h[x]^i.se;\n\t\t\tdfs(i.fi);\n\t\t}\n\t}\n\treturn ;\n}\nsigned main(){\n\tios::sync_with_stdio(0);\n\tcin.tie(0);cout.tie(0);\n\tcin>>n>>m>>q;\n\tfor(int i=1;i<=m;i++){\n\t\tint x,y,v;cin>>x>>y>>v;\n\t\tG1[x].push_back({y,v});G1[y].push_back({x,v});\n\t}\n\t//for(auto i:G1[25061]) cout<<i.fi<<\" \"<<i.se<<endl;\n\tdfs(1);\n\t//cout<<\"%%%\"<<endl;\n\t//for(int i=1;i<=n;i++) cout<<h[i]<<'\\n';\n\twhile(q--){\n\t\tint x,y;cin>>x>>y;\n\t\tint cnt=(h[x]^h[y]);\n\t\tcout<<cnt<<'\\n';\n\t}\n\treturn 0;\n}\n",
