    "题目专辑\\字符串\\字符串匹配\\代码--xesir.cpp": "#include <bits/stdc++.h>\nusing namespace std;\n#define int long long\n#define ull unsigned long long\n#define PUU pair<ull,ull> \n#define fi first\n#define se second\nconst int N=2e6+10,mod1=998244353,mod2=1e9+7;\nint thp[27];\nPUU hs[N],pb[N];\nint pre[N],suf[N];\ninline PUU gths(int l,int r){\n    PUU res;\n    res.fi=(hs[r].fi%mod1+mod1-hs[l-1].fi*pb[r-l+1].fi%mod1)%mod1;\n    res.se=(hs[r].se-hs[l-1].se*pb[r-l+1].se);\n    return res;\n}\nsigned main(){\n    ios::sync_with_stdio(0);\n    cin.tie(0);cout.tie(0);\n    int t;cin>>t;\n    pb[0].fi=1,pb[0].se=1;\n    for(int i=1;i<1.5e6;i++) \n        pb[i].fi=pb[i-1].fi*26%mod1,pb[i].se=pb[i-1].se*26;\n    while(t--){\n        string s;cin>>s;s='0'+s;\n        int n=s.size()-1;ull ans=0;\n        for(int i=0;i<=26;i++) thp[i]=0;\n        for(int i=1;i<=n;i++) \n            hs[i].fi=(hs[i-1].fi*26%mod1+(s[i]-'a')%mod1)%mod1,            hs[i].se=(hs[i-1].se*26+(s[i]-'a'));\n        for(int i=1,j=0;i<=n;i++){\n            j^=(1<<(s[i]-'a'));\n            pre[i]=__builtin_popcountll(j);\n        }\n        for(int i=n,j=0;i>0;i--){\n            j^=(1<<(s[i]-'a'));\n            suf[i]=__builtin_popcountll(j);\n        }\n        for(int i=2;i<n;i++){\n            //bool kk=true;\n            for(int k=pre[i-1];k<=26;k++) thp[k]++;\n            for(int j=0;(j+1)*i<n;j++){\n                if(hs[i]==gths(1+i*j,i*(j+1))){\n                    ans+=thp[suf[i*(j+1)+1]];\n                }else break;\n            }\n        }\n        cout<<ans<<'\\n';\n    }\n    return 0;\n}\n",
    "题目专辑\\动态规划\\括号序列\\代码--xesir.cpp": "#include<bits/stdc++.h>\r\n#define endl '\\n'\r\n#define fi first\r\n#define se second\r\n#define lowbit(x) (x&(-x))\r\n#define int long long\r\nusing namespace std;\r\ntypedef pair<int,int> PII;\r\ntypedef long long ll;\r\nconst int N=510,mod=1e9+7;\r\nint cnt=0,n,k;\r\nstring s;\r\nint sr[N][N],b[N][N],f[N][N],h[N][N],c[N][N],tr[N][N];\r\nbool cmk(int l,int r){\r\n\tif((s[l]=='('||s[l]=='?')&&(s[r]==')'||s[r]=='?')) return true;\r\n\telse return false;\r\n}\r\nsigned main(){\r\n//    freopen(\".in\",\"r\",stdin);\r\n//    freopen(\".out\",\"w\",stdout);\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);cout.tie(nullptr);\r\n    cin>>n>>k;\r\n    cin>>s;s=' '+s;\r\n    for(int i=1;i<=n;i++){\r\n        //cout<<s[i];\r\n        sr[i][i-1]=1;\r\n    }\r\n\tfor(int len=1;len<=n;len++){\r\n\t\tfor(int l=1;l<=n-len+1;l++){\r\n\t\t\tint r=l+len-1;\r\n            //if(len<=k&&sr[l+1][r]==1&&(s[l]=='*'||s[l]=='?')) sr[l][r]=1;\r\n\t\t\tif(len<=k&&sr[l][r-1]==1&&(s[r]=='*'||s[r]=='?')) sr[l][r]=1;\r\n\t\t\tif(len>=2){\r\n                bool u=cmk(l,r);\r\n                //cout<<u<<\" \"<<l<<\" \"<<r<<\"\\n\";\r\n                if(u) b[l][r]=(sr[l+1][r-1]%mod+f[l+1][r-1]%mod+h[l+1][r-1]%mod+c[l+1][r-1]%mod)%mod;\r\n\t\t\t    for(int i=l;i<r;i++){\r\n\t\t\t\t    f[l][r]=(f[l][r]%mod+h[l][i]*sr[i+1][r]%mod)%mod;\r\n\t\t\t\t    h[l][r]=(h[l][r]%mod+(f[l][i]+h[l][i])*b[i+1][r]%mod)%mod;\r\n    \t\t\t\tc[l][r]=(c[l][r]%mod+(c[l][i]+tr[l][i])*b[i+1][r]%mod)%mod;\r\n\t\t\t\t    tr[l][r]=(tr[l][r]%mod+c[l][i]*sr[i+1][r]%mod)%mod;\r\n    \t\t\t}\r\n            }\r\n            h[l][r]=(h[l][r]%mod+b[l][r]%mod)%mod;\r\n\t\t\ttr[l][r]=(tr[l][r]%mod+sr[l][r]%mod)%mod;\r\n\t\t}\r\n    }\r\n    cout<<h[1][n];\r\n\t// for(int len=1;len<=n;len++){\r\n //        for(int l=1;l+len-1<=n;l++){\r\n //            int r=len+l-1;\r\n //            cout<<l<<\" \"<<r<<\" \"<<sr[l][r]<<\" \"<<b[l][r]<<\" \"<<f[l][r]<<\" \"<<h[l][r]<<\" \"<<c[l][r]<<\" \"<<tr[l][r]<<\"\\n\";\r\n //        }\r\n //    }\r\n\treturn 0;\r\n}\r\n",
